const game = {
  newMatch(ctx) {
    const deck = Array.from({length:52}, (_, index) => index);
    let seed = 2166136261;
    for (const player of ctx.players) {
      for (const letter of player.id) seed = Math.imul(seed ^ letter.charCodeAt(0), 16777619);
    }
    for (let index = 51; index > 0; index--) {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      const other = seed % (index + 1);
      [deck[index], deck[other]] = [deck[other], deck[index]];
    }
    const hands = ctx.players.map((_, seat) => deck.filter((_, index) => index % ctx.players.length === seat));
    return {state:{hands,pile:[],seat:0,flips:0,winners:[]},turn:[ctx.players[0].id]};
  },
  applyMove(s, id, move, ctx) {
    if (!move || Object.keys(move).length !== 1 || s.winners.length ||
        ctx.players[s.seat].id !== id || !["flip","slap"].includes(move.action)) {
      throw new InvalidMove("Choose a legal move on your turn.");
    }
    const hands = s.hands.map(hand => [...hand]);
    let pile = [...s.pile];
    const jack = pile.length > 0 && pile[pile.length-1] % 13 === 9;
    let flips = s.flips;
    if (move.action === "slap" && jack) {
      hands[s.seat].push(...pile);
      pile = [];
    } else if (move.action === "slap") {
      const top = hands[s.seat].shift();
      if (top !== undefined) {
        const recipient = hands.findIndex((hand, seat) => seat !== s.seat && hand.length);
        hands[recipient].push(top);
      }
      flips++;
    } else {
      pile.push(hands[s.seat].shift());
      flips++;
    }
    const counts = hands.map(hand => hand.length);
    const terminal = counts.filter(Boolean).length <= 1 || flips >= 140;
    const winners = terminal ? counts.flatMap((count, seat) => count === Math.max(...counts) ? [seat] : []) : [];
    let seat = s.seat;
    do { seat = (seat + 1) % hands.length; } while (!counts[seat]);
    const state = {hands,pile,seat,flips,winners};
    if (!terminal) return {state,turn:[ctx.players[seat].id]};
    const humans = ctx.players.filter(player => player.kind === "human" && player.active !== false);
    const winningHumans = humans.filter(player => winners.includes(ctx.players.indexOf(player)));
    const paid = winningHumans.length ? winningHumans : humans;
    return {state,turn:null,payouts:Object.fromEntries(paid.map((player, index) => [
      player.id, Math.floor(ctx.pot / paid.length) + (index < ctx.pot % paid.length ? 1 : 0)
    ]))};
  },
  viewFor(s) {
    return {counts:s.hands.map(hand => hand.length),top:s.pile[s.pile.length-1] ?? null,
      pileCount:s.pile.length,seat:s.seat,flips:s.flips,winners:s.winners};
  },
  computerMove(s) {
    return {action:s.pile.length && s.pile[s.pile.length-1] % 13 === 9 ? "slap" : "flip"};
  },
  randomMove(s) { return this.computerMove(s); }
};

